', '[\"productos/multimedia/chocolate-para-taza-puro-cacao/chocolate-taza2.jpg\"]', '{\"Talla\":[],\"Color\":[],\"Marca\":[\"Mono Tingales\"]}', 10, 0, 'productos/portadas/chocolate-para-taza-puro-cacao.png', 3803, 399, 0, 0, 0, 0, 0, 0, 0, '', '0000-00-00 00:00:00', 0, 0, NULL, 88, 131, 11, NULL, '2026-07-27 12:16:45');
