INSERT INTO productos (id, tipo, ruta, estado, titulo, titular, descripcion, multimedia, detalles, precio, stock, portada, vistas, ventas, vistasGratis, ventasGratis, ofertadoPorCategoria, ofertadoPorSubCategoria, oferta, precioOferta, descuentoOferta, imgOferta, finOferta, peso, entrega, costo_envio, categoria_id, subcategoria_id, marca_id, proveedor_id, fecha) VALUES (131, 'fisico', 'cafetera-expreso-3-en-1', 1, 'cafetera expreso 3 en 1', 'Molinillo de caf├® autom├ítico de 2.0L y cafetera expreso 3 en 1...', '<p>Molinillo de café automático de 2.0L y cafetera expreso 3 en 1</p>
<p>220-240 V, 50/60 Hz, 1350-1550 W</p>
<p>Capacidad┬á:┬á2.0L</p>
<p>Tolva de frijoles: 250g</p>
<p>Embudo de cocción de 58 mm de fundición a presión de Alminum, filtro SUS para taza individual y taza doble, cono palstic, jarra de leche 460, cepillo de limpieza, pin de limpieza incluido.</p>
<p>Sistema de molienda de rebabas cónicas, café fino ajustable con ajuste de molido de 30</p>
<p>Tamaño de la unidad┬á:┬áL * W * H┬á:┬á340 mm ú 332 mm ú 395 mm</p>
<p>Molinillo y sistema de canal de polvo vertical, sin polvo atrapado,┬á┬árebaba desmontable para una limpieza conveniente.</p>
<p>Control de temperatura inteligente PID de alta precisión para una temperatura precisa y estable</p>
<p>Temperatura en el centro del potrafiltro: 92 ┬▒ 2 ┬░ C</p>
<p>La eficiencia térmica del sistema de elaboración de cerveza supera el 90%</p>
<p>El precalentamiento se puede terminar en 40S</p>
<p>Presión de la bomba: 15 bar</p>
<p>Puede preparar café de taza grande y taza pequeña automáticamente.</p>
<p>Con función de agua caliente</p>
<p>Con medidor de flujo para controlar el flujo con precisión y la tolerancia de salida de café es ┬▒┬á1┬á5┬á%┬áml</p>
<p>Función de apagado automático</p>
<p><strong>Con medidor de presión┬á</strong></p>', '[\"productos/multimedia/cafetera-expreso-3-en-1-/cafetera-molinillo.jpg\",\"productos/multimedia/cafetera-expreso-3-en-1-/cafetera-molinillo-largo.jpg\"]', '{\"Talla\":[],\"Color\":[],\"Marca\":[\"DCAFCONDOR\"]}', 1665, 0, 'productos/portadas/cafetera-expreso-3-en-1-.jpg', 816, 40, 0, 0, 0, 0, 0, 0, 0, '', '0000-00-00 00:00:00', 0, 5, NULL, 89, 133, 11, NULL, '2026-07-27 12:16:45');
